Sure, here's an implementation of Depth First Search (DFS) algorithm in C++ for a graph represented using adjacency list:
```cpp
#include <iostream>
#include <vector>
using namespace std;

// Recursive helper function for DFS traversal
void dfs_helper(vector<vector<int>>& graph, int node, vector<bool>& visited) {
    // Mark the current node as visited
    visited[node] = true;
    cout << node << " ";

    // Recur for all the adjacent vertices
    for (int i = 0; i < graph[node].size(); i++) {
        int adj = graph[node][i];
        if (!visited[adj])
            dfs_helper(graph, adj, visited);
    }
}

// DFS traversal of the graph
void dfs(vector<vector<int>>& graph, int start) {
    vector<bool> visited(graph.size(), false);
    dfs_helper(graph, start, visited);
}

int main() {
    int V = 5;
    vector<vector<int>> graph(V);

    // Add edges
    graph[0].push_back(1);
    graph[0].push_back(2);
    graph[1].push_back(2);
    graph[2].push_back(0);
    graph[2].push_back(3);
    graph[3].push_back(3);

    cout << "DFS traversal starting from node 2:\n";
    dfs(graph, 2);

    return 0;
}
```
Here's the visualization of the DFS traversal starting from node 2 for the given graph:
```csharp
      2
     / \
    0   3
   / \
  1   2

DFS traversal starting from node 2:
2 0 1 3
```
As we start the DFS traversal from node 2, we first visit 2 and mark it as visited. Then, we explore its adjacent vertices in the order 0 and 3. We visit 0 and mark it as visited, then explore its adjacent vertices in the order 1 and 2. We visit 1 and mark it as visited, and then we backtrack to vertex 0 and visit vertex 2. We had already marked 2 as visited, so we backtrack to vertex 2 and visit vertex 3. We mark 3 as visited and complete the traversal.

Sure, here is an implementation of BFS (Breadth-First Search) in C++ and a visualization of the algorithm applied to a simple graph:
```arduino
#include <iostream>
#include <queue>
#include <vector>

using namespace std;

void bfs(vector<vector<int>> &graph, int start) {
    int n = graph.size();
    vector<bool> visited(n, false);
    queue<int> q;

    visited[start] = true;
    q.push(start);

    while (!q.empty()) {
        int cur = q.front();
        q.pop();

        cout << cur << " ";

        for (int i = 0; i < graph[cur].size(); i++) {
            int neighbor = graph[cur][i];
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                q.push(neighbor);
            }
        }
    }
}

int main() {
    // Define the graph as an adjacency list
    vector<vector<int>> graph = {
        {1, 2},
        {0, 3, 4},
        {0, 5},
        {1},
        {1, 6},
        {2},
        {4}
    };

    // Perform BFS starting from node 0
    bfs(graph, 0);

    return 0;
}
```
Here's a visualization of the algorithm applied to the same graph:
```vbnet
Starting from node 0:
- Visit node 0 and add it to the queue: queue = {0}
Queue: 0
Visited: [1, 0, 0, 0, 0, 0, 0]

- Visit the first node in the queue (node 0):
  - Visit its neighbors (nodes 1 and 2) and add them to the queue: queue = {1, 2}
Queue: 1, 2
Visited: [1, 1, 1, 0, 0, 0, 0]

- Visit the next node in the queue (node 1):
  - Visit its neighbors (nodes 0, 3, and 4) and add them to the queue (nodes 3 and 4 are already in the queue): queue = {2, 3, 4}
Queue: 2, 3, 4
Visited: [1, 1, 1, 1, 1, 0, 0]

- Visit the next node in the queue (node 2):
  - Visit its neighbor (node 5) and add it to the queue: queue = {3, 4, 5}
Queue: 3, 4, 5
Visited: [1, 1, 1, 1, 1, 1, 0]

- Visit the next node in the queue (node 3):
  - Visit its neighbor (node 1), but it has already been visited, so do nothing.

- Visit the next node in the queue (node 4):
  - Visit its neighbor (node 6) and add it to the queue: queue = {5, 6}
Queue: 5, 6
Visited: [1, 1, 1, 1, 1, 1, 1]

- Visit the next node in the queue (node 5):
  - It has no neighbors to visit, so do nothing.

- Visit the next node in the queue (node 6):
  - It has no neighbors to visit, so do nothing.

The BFS traversal of the graph starting from node 0 is: 0 1 2 3 4 5 6
```

